import {createSubjectTools} from './subject-tools.js';
import {createPendulumLab} from './pendulum-lab.js';
import {createMathBoardTools} from './math-board-view.js';
import {openHealthQuiz} from './health-quiz.js';
import {openMusicQuiz} from './music-symbols.js';
import {createArtTools} from './art-view.js';
import {createLearningTools} from './learning-view.js';
import {binomialProbabilities} from './galton.js';
export const PALETTE=['#f2ead5','#e6c775','#d89583','#88b5ab','#91aac6'];
export function lightColor(r,g,b){return `rgb(${[r,g,b].map(v=>Math.round(Math.max(0,Math.min(100,Number(v)||0))*2.55)).join(',')})`;}
export function createSchoolTools({ui,getView,canSave=()=>true,reduced=false,throwing=null,passing=null,race=null,baseball=null,music=null,audio=null,equations=null,science=null}){
 const subjects=createSubjectTools({ui,onKoreanQuestion:index=>getView()?.schoolView?.updateKoreanQuestion(index),onEnglishQuestion:q=>getView()?.schoolView?.updateEnglishQuestion(q),speechAudio:audio});
 const drawings=new Map();
 const lab=science??createPendulumLab({ui});
 const art=createArtTools({ui,getView,canSave});
 const math=equations??createMathBoardTools({ui,getView,canSave});
 const learning=createLearningTools({ui,applyArt:canvas=>art.applyArt(canvas),getAudio:audio?()=>audio.unlock():null});
 const $=s=>document.querySelector(s);
 function open(title,body,mount){return ui.workshop(title,body,mount);}
 function paint(chalk=true){const id='math.board',bg='#275b45';
  open(chalk?'초록 칠판 · 나의 분필':'물감 미술실 · 나의 그림',`<p>손가락이나 마우스로 그려요. 키보드는 방향키로 점을 옮기고 Space로 선을 그려요.</p><div class="school-palette" role="group" aria-label="그림 색">${(chalk?PALETTE:['#c67566','#dfb954','#669588','#7299b5','#655c88','#f6e8c8']).map((c,i)=>`<button data-paint-color="${c}" style="--swatch:${c}" aria-label="색 ${i+1}" aria-pressed="${i===0}"></button>`).join('')}</div><canvas id="school-drawing" class="school-canvas" width="720" height="440" tabindex="0" aria-label="${chalk?'초록 칠판':'그림 종이'} 그리기 영역"></canvas>${chalk?'<div class="math-lesson-reading"><p>y = (x − 1)² − 4, −1 ≤ x ≤ 4<br>최솟값 −4 (x = 1), 최댓값 5 (x = 4)</p><p>x² + y² = 25와 y = 3의 교점<br>(−4, 3), (4, 3)</p></div>':''}<div class="school-tool-row">${['+','−','×','÷','=','π','√','∞'].map(t=>`<button data-stamp="${t}">${t}</button>`).join('')}</div><div class="school-tool-row"><button id="drawing-undo">한 줄 되돌리기</button><button id="drawing-clear">전체 지우기</button></div><p class="caption">그림은 이번 방문 동안 남아요. 모은 별과 기존 저장은 그대로예요.</p>`,()=>{
   const c=$('#school-drawing'),ctx=c.getContext('2d'),history=[],surface=getView()?.schoolView?.drawingSurfaces[id];let color=(chalk?PALETTE:['#c67566'])[0],drawing=false,last=null,cursor={x:360,y:220};
   ctx.fillStyle=bg;ctx.fillRect(0,0,720,440);const saved=drawings.get(id)??surface?.canvas;if(saved)ctx.drawImage(saved,0,0,720,440);
   const commit=()=>{const saved=document.createElement('canvas');saved.width=720;saved.height=440;saved.getContext('2d').drawImage(c,0,0);drawings.set(id,saved);getView()?.schoolView?.updateDrawing(id,c);};
   const checkpoint=()=>{history.push(ctx.getImageData(0,0,720,440));if(history.length>20)history.shift();};
   const point=e=>{const r=c.getBoundingClientRect();const bx=c.clientLeft||0,by=c.clientTop||0,w=c.clientWidth||r.width,h=c.clientHeight||r.height;return{x:Math.max(0,Math.min(720,(e.clientX-r.left-bx)*720/w)),y:Math.max(0,Math.min(440,(e.clientY-r.top-by)*440/h))};};
   const line=(a,b)=>{ctx.strokeStyle=color;ctx.lineWidth=chalk?5:8;ctx.lineCap='round';ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(b.x,b.y);ctx.stroke();commit();};
   c.onpointerdown=e=>{e.preventDefault();checkpoint();drawing=true;last=point(e);line(last,{x:last.x+.1,y:last.y+.1});c.setPointerCapture(e.pointerId);};c.onpointermove=e=>{if(drawing){const p=point(e);line(last,p);last=p;}};c.onpointerup=c.onpointercancel=()=>{drawing=false;};
   c.onkeydown=e=>{const d={ArrowLeft:[-12,0],ArrowRight:[12,0],ArrowUp:[0,-12],ArrowDown:[0,12]}[e.key];if(d){e.preventDefault();const next={x:Math.max(0,Math.min(720,cursor.x+d[0])),y:Math.max(0,Math.min(440,cursor.y+d[1]))};if(e.shiftKey){checkpoint();line(cursor,next);}cursor=next;}if(e.code==='Space'){e.preventDefault();checkpoint();line(cursor,{x:cursor.x+8,y:cursor.y});cursor.x+=8;}};
   document.querySelectorAll('[data-paint-color]').forEach(b=>b.onclick=()=>{color=b.dataset.paintColor;document.querySelectorAll('[data-paint-color]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));});
   document.querySelectorAll('[data-stamp]').forEach(b=>b.onclick=()=>{checkpoint();ctx.fillStyle=color;ctx.font='700 52px "Dormi Gentle Pen", serif';ctx.fillText(b.dataset.stamp,cursor.x,cursor.y);cursor.x=(cursor.x+65)%660;commit();});
   $('#drawing-undo').onclick=()=>{if(history.length){ctx.putImageData(history.pop(),0,0);commit();}};$('#drawing-clear').onclick=()=>{checkpoint();ctx.fillStyle=bg;ctx.fillRect(0,0,720,440);commit();};return commit;
  });
 }
 function light(){open('빛의 색을 섞어 보기',`<p>빨강·초록·파랑 빛을 더하는 화면 모형이에요. 물감 섞기와는 달라요.</p><div id="light-result" class="light-result" role="img" aria-label="섞인 빛의 색"></div>${['빨강','초록','파랑'].map((n,i)=>`<label class="school-slider">${n}<input data-light="${i}" type="range" min="0" max="100" value="${i===0?80:20}"><output data-light-value="${i}"></output></label>`).join('')}<p id="light-status" role="status"></p>`,()=>{const sliders=[...document.querySelectorAll('[data-light]')],update=()=>{const values=sliders.map(s=>s.value);$('#light-result').style.background=lightColor(...values);document.querySelectorAll('[data-light-value]').forEach((o,i)=>o.textContent=values[i]+'%');$('#light-status').textContent=`빨강 ${values[0]} · 초록 ${values[1]} · 파랑 ${values[2]}`;};sliders.forEach(s=>s.oninput=update);update();});}
 function galton(){const simulation=getView()?.schoolView?.galton;if(!simulation)return;open('벽의 갈톤보드',`<p>8번의 선택이 서로 독립이고, 매번 왼쪽·오른쪽을 각각 50%로 고른다고 가정하는 이항분포 경로 모형이에요. 고교 선택 과목 ‘확률과 통계’에 연결돼요. 실제 구슬 충돌 물리를 그대로 재현한 실험은 아니에요.</p><div class="school-tool-row"><label>구슬 수 <select id="galton-count"><option>30</option><option selected>100</option><option>300</option></select></label><button id="galton-start">시작</button><button id="galton-pause">멈춤</button><button id="galton-reset">초기화</button></div><canvas id="galton-canvas" class="school-canvas galton-canvas" width="720" height="600" aria-label="실제 선택 경로를 따라 내려오는 구슬과 도착 개수 그래프"></canvas><p id="galton-status" role="status"></p><p class="caption">초록 막대: 전체 예정 구슬 중 도착 비율 · 금색 점: 이론 확률<br>완료 후 두 값을 비교해요. 구슬 수는 표본 수이고, 각 구슬의 선택 횟수는 8번으로 같아요. 구슬을 늘려도 매번 더 매끈해지거나 정규분포가 보장되지는 않아요.</p><div id="galton-bins" class="galton-bins" aria-label="칸별 구슬 수"></div>`,()=>{const c=$('#galton-canvas'),ctx=c.getContext('2d'),expected=binomialProbabilities(8);let frame;$('#galton-count').value=String(simulation.snapshot().total);$('#galton-start').onclick=()=>simulation.start();$('#galton-pause').onclick=()=>simulation.pause();const reset=()=>simulation.reset(Number($('#galton-count').value));$('#galton-reset').onclick=reset;$('#galton-count').onchange=reset;const draw=()=>{const s=simulation.snapshot();ctx.fillStyle='#244e43';ctx.fillRect(0,0,720,600);ctx.fillStyle='#ddc484';for(let row=0;row<8;row++)for(let i=0;i<=row;i++){ctx.beginPath();ctx.arc(360+(i-row/2)*62,52+row*40,4,0,Math.PI*2);ctx.fill();}ctx.fillStyle='#ffc47b';for(const b of s.balls)if(!b.done){ctx.beginPath();ctx.arc(360+b.x*62,52-b.y*40,6,0,Math.PI*2);ctx.fill();}for(let i=0;i<9;i++){const x=360+(i-4)*62,h=s.bins[i]/s.total*450;ctx.fillStyle='#a6d1af';ctx.fillRect(x-21,548-h,42,h);ctx.fillStyle='#e3bc64';ctx.beginPath();ctx.arc(x,548-expected[i]*450,4,0,Math.PI*2);ctx.fill();ctx.fillStyle='#f0e7cd';ctx.font='700 22px "Dormi Gentle Pen", sans-serif';ctx.textAlign='center';ctx.fillText(String(i),x,579);}$('#galton-status').textContent=`${s.running?'움직이는 중':'멈춤'} · 대기 ${s.total-s.released} + 내려오는 중 ${s.inFlight} + 도착 ${s.landed} = ${s.total}개`;$('#galton-bins').textContent=s.bins.map((n,i)=>`${i}칸: ${n}`).join(' · ');$('#galton-start').disabled=s.running||s.landed===s.total;$('#galton-pause').disabled=!s.running;frame=requestAnimationFrame(draw);};draw();return()=>{cancelAnimationFrame(frame);simulation.pause();};});}
 return {open(target){if(['englishListening','englishSentences','englishRoleplay','englishDictionary','storyOrder','wordMatch','worldMap','koreanSpelling','koreanComposition','koreanDictionary','koreanHistory'].includes(target.tool))return subjects.open(target.tool);if(target.tool==='passing'||target.tool==='learning'&&target.lesson==='sports'&&passing)passing?.open(target.partnerId);else if(target.tool==='race')race?.open();else if(target.tool==='baseball')baseball?.open();else if(target.tool==='throw')throwing?.open();else if(target.tool==='learning')learning.open(target.lesson);else if(target.tool==='paint')art.open();else if(target.tool==='chalkboard')math.open();else if(target.tool==='chalkboardLegacy')paint(true);else if(['piano','listen','cello','harp'].includes(target.tool))music?.open(target.tool);else if(target.tool==='healthQuiz')openHealthQuiz(ui);else if(target.tool==='musicQuiz')openMusicQuiz(ui,{onQuestion:index=>getView()?.schoolView?.updateMusicQuiz(index)});else if(target.tool==='observe')lab.open();else if(target.tool==='light')light();else if(target.tool==='galton')galton();else if(target.tool==='ball'){getView()?.schoolView?.kickBall();ui.toast('톡! 공이 골대를 향해 굴러가요 ⚽');}},restore(view){for(const [id,c]of drawings)view.schoolView?.updateDrawing(id,c);art.restore(view);math.restore(view);},cancel(){subjects.cancel();lab.close();art.cancel();math.cancel();passing?.close();race?.close();baseball?.close();throwing?.close();if(music?.cancel)music.cancel();else music?.close();},get throwing(){return !!throwing?.active;},get throwCamera(){return throwing?.camera;},throwViewport:(w,h)=>throwing?.viewport(w,h),tick:dt=>throwing?.tick(dt),throwSnapshot:()=>throwing?.snapshot(),resetArt:async()=>{const a=await art.reset();const m=await math.reset();return a&&m;}};
}
